WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, attr_value), enriched AS (SELECT id, service, latency_ms, key, attr_value, AVG(latency_ms) OVER (PARTITION BY host ORDER BY latency_ms ASC, id ASC, key ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS latency_ms_avg_3, NTILE(5) OVER (PARTITION BY host, service ORDER BY latency_ms DESC, id ASC, key ASC) AS latency_ms_bucket, DENSE_RANK() OVER (ORDER BY latency_ms DESC NULLS LAST) AS latency_ms_dense_rank, ROW_NUMBER() OVER (PARTITION BY service ORDER BY log_ts DESC, id ASC, key ASC) AS row_seq FROM flattened), valid AS (SELECT id, latency_ms, key, attr_value, latency_ms_avg_3, latency_ms_dense_rank, row_seq, CAST(row_seq AS STRING) AS row_seq_str, latency_ms_bucket + latency_ms_dense_rank AS latency_ms_bucket_plus_latency_ms_dense_rank FROM enriched WHERE key IS NOT NULL), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY key ORDER BY latency_ms_avg_3 ASC NULLS LAST, id ASC, key ASC) AS dedup_rank FROM valid) t WHERE dedup_rank = 1), metrics AS (SELECT *, LEAD(row_seq, 1, 0) OVER (ORDER BY latency_ms_avg_3 ASC, id ASC, key ASC) AS next_row_seq, LEAD(latency_ms, 2) OVER (PARTITION BY key ORDER BY latency_ms ASC, id ASC, key ASC) AS next_latency_ms FROM latest), metrics_app_logs AS (SELECT id, latency_ms, key, latency_ms_avg_3, row_seq_str, latency_ms_bucket_plus_latency_ms_dense_rank, next_latency_ms, LAG(row_seq) OVER w_grp AS prev_row_seq, LEAD(row_seq) OVER w_grp AS next_row_seq_2, LAG(next_latency_ms) OVER w_grp AS prev_next_latency_ms, ROW_NUMBER() OVER w_grp AS event_seq FROM metrics WINDOW w_grp AS (PARTITION BY key ORDER BY latency_ms_bucket_plus_latency_ms_dense_rank ASC, id ASC, key ASC)) SELECT key, COUNT_IF(key = 'version') AS version_events, SUM(prev_next_latency_ms) FILTER (WHERE key = 'trace') AS trace_total_prev_next_latency_ms, STDDEV_SAMP(latency_ms) AS latency_ms_stddev FROM metrics_app_logs GROUP BY 1 HAVING latency_ms_stddev < 1000000 ORDER BY key ASC NULLS FIRST
